"""9s62 · PLAIN WORDS WHEN THE STORE REFUSES: Files, the new file, the text editor; and a line when the device has no store at all."""
def apply(P):
    P.replace_once("filesPut(rec).then(function(){ n++; filesPaint(); diary('file','brought in '+f.name); });",
                   "filesPut(rec).then(function(){ n++; filesPaint(); diary('file','brought in '+f.name); }).catch(function(e){ var w=storeWhy(e, f.name); window.__filesWarn={t:Date.now(), text:w}; state('filesState', w, 'warn'); });   /* 9s62: a refusal is said, never swallowed, and stays while the other files are counted */", 'filesTake catch')
    # the Files room's count never paints over a refusal said in the last twenty seconds (measured: the second file's success hid the first's refusal)
    P.replace_once("    state('filesState', list.length? list.length+' kept on this device':'nothing kept yet', list.length?'ok':'');",
                   "    var __w=(window.__filesWarn&&Date.now()-window.__filesWarn.t<20000)?window.__filesWarn.text:''; state('filesState', __w||(list.length? list.length+' kept on this device':'nothing kept yet'), __w?'warn':(list.length?'ok':''));   /* 9s62: a recent refusal stays in view */", 'filesPaint keeps the refusal')
    # a full device aborts the transaction without an error event, and the error stands on the request first (measured in Chromium): both are heard
    P.replace_once("function filesPut(rec){ return filesOpen().then(function(d){ return new Promise(function(res,rej){ var t=d.transaction('files','readwrite'); t.objectStore('files').put(rec); t.oncomplete=function(){ res(rec); }; t.onerror=function(){ rej(t.error); }; }); }); }",
                   "function filesPut(rec){ return filesOpen().then(function(d){ return new Promise(function(res,rej){ var t, q; try{ t=d.transaction('files','readwrite'); q=t.objectStore('files').put(rec); }catch(e){ rej(e); return; }\n"
                   "  /* 9s62: a full device aborts the transaction with no error event, and the error stands on the request before it reaches the transaction (measured in Chromium): both are heard, so the refusal is said and the promise settles */\n"
                   "  function why(ev){ var e=t.error||(ev&&ev.target&&ev.target.error)||(q&&q.error); if(!e){ e=new Error('aborted'); e.name='AbortError'; } return e; }\n"
                   "  t.oncomplete=function(){ res(rec); }; t.onerror=function(ev){ rej(why(ev)); }; t.onabort=function(ev){ rej(why(ev)); }; }); }); }", 'filesPut hears abort')
    P.replace_once("filesPut(rec).then(function(){ filesPaint(); filesShow(rec, rec.kind==='page'); pageTabs('files','kept'); diary('file','made '+name); });",
                   "filesPut(rec).then(function(){ filesPaint(); filesShow(rec, rec.kind==='page'); pageTabs('files','kept'); diary('file','made '+name); }).catch(function(e){ state('filesState', storeWhy(e, name), 'warn'); });", 'newMake catch')
    P.replace_once("filesPut(FEDIT).then(function(){ state('fileEditState', FEDIT.name+' \\u00b7 kept','ok'); filesPaint(); diary('file','kept a change in '+FEDIT.name); });",
                   "filesPut(FEDIT).then(function(){ state('fileEditState', FEDIT.name+' \\u00b7 kept','ok'); filesPaint(); diary('file','kept a change in '+FEDIT.name); }).catch(function(e){ state('fileEditState', storeWhy(e, FEDIT.name), 'warn'); });", 'fileEditSave catch')
    # the words, one function, before the Files room's code
    P.insert_before("var FDB=null;\nfunction filesOpen(){",
        "/* 9s62: why the store refused, in plain words, with the way out: a full device, a store switched off (a private window), or a fault */\n"
        "function storeWhy(e, name){ var fr=(document.documentElement.lang==='fr'), n=(e&&(e.name||''))||'', m=String(e&&(e.message||e)||'');\n"
        "  if(/Quota/i.test(n)||/quota|full|space/i.test(m)) return fr?('Plus de place sur cet appareil pour garder '+name+'. Ce qui était gardé reste. Libérez de la place : Réglages, Sauvegarde, Stockage (Nettoyer la bibliothèque), ou retirez ici un fichier.'):('No room left on this device to keep '+name+'. What was kept before stays. Free some space: Settings, Backup, Storage (Clean the library), or remove a file here.');\n"
        "  if(/InvalidState|NotFound|Version|blocked|Security/i.test(n)||!window.indexedDB||/reading 'open'|indexedDB|Indexed Database/i.test(m)) return fr?('Le stockage de cet appareil est fermé à la Forge (une fenêtre privée, ou le stockage refusé). '+name+' n’a pas été gardé ; téléchargez-le plutôt.'):('This device’s storage is closed to the Forge (a private window, or storage refused). '+name+' was not kept; download it instead.');\n"
        "  return fr?('Le stockage a refusé '+name+' ('+(n||m).slice(0,80)+'). Essayez de nouveau ; si cela se répète, téléchargez le fichier.'):('The store refused '+name+' ('+(n||m).slice(0,80)+'). Try again; if it keeps happening, download the file instead.'); }\n", 'storeWhy')
    # the Files room says at once when the device offers no store
    P.replace_once("}).catch(function(e){ state('filesState','the store refused: '+e,'warn'); });\n}", "}).catch(function(e){ if(!window.indexedDB) return; /* the health line below says it, once */ state('filesState', storeWhy(e, document.documentElement.lang==='fr'?'les fichiers':'files'), 'warn'); });   /* 9s62: plain words */\n}", 'filesPaint catch')
    P.replace_once("  filesPaint();\n})();\n\n/* ===================== FONTES, the coding well, and the RECKONER, the calculator for code ===================== */",
                   "  filesPaint();\n  /* 9s62: no store at all (IndexedDB missing or refused) is said once, plainly, instead of a silent empty list */\n  try{ if(!window.indexedDB) state('filesState', document.documentElement.lang==='fr'?'cet appareil n’offre pas de stockage à la Forge : les fichiers ne peuvent pas être gardés ici':'this device offers the Forge no store: files cannot be kept here','warn'); else filesOpen().catch(function(e){ state('filesState', storeWhy(e, document.documentElement.lang==='fr'?'les fichiers':'files'), 'warn'); }); }catch(e){}\n})();\n\n/* ===================== FONTES, the coding well, and the RECKONER, the calculator for code ===================== */", 'files store health')
